issue.body:
Jira Link: [DB-3957](https://yugabyte.atlassian.net/browse/DB-3957)
### Description

It would be useful to have a protobuf to jsonb (or json) converter so that we can easily add functions that return jsonb.  For instance, yb_servers function makes an RPC call (involving protobufs) and puts it in multiple output columns.  As more return items are added, the function grows more columns, and each require a migration file because the function output schema changes.  **To minimize such schema changes, the function could return a jsonb, and if the jsonb schema changes, no migration is needed.**

Jsonb can be output using `JsonbPGetDatum`.  This takes a `Jsonb` value, which is the disk representation of the in-memory `JsonbValue`.  `JsonbValue` looks like

```
struct JsonbValue
{
	enum jbvType type;			/* Influences sort order */

	union
	{
		Numeric numeric;
		bool		boolean;
		struct
		{
			int			len;
			char	   *val;	/* Not necessarily null-terminated */
		}			string;		/* String primitive type */

		struct
		{
			int			nElems;
			JsonbValue *elems;
			bool		rawScalar;	/* Top-level "raw scalar" array? */
		}			array;		/* Array container type */

		struct
		{
			int			nPairs; /* 1 pair, 2 elements */
			JsonbPair  *pairs;
		}			object;		/* Associative container type */

		struct
		{
			int			len;
			JsonbContainer *data;
		}			binary;		/* Array or object, in on-disk format */

		struct
		{
			Datum		value;
			Oid			typid;
			int32		typmod;
			int			tz;		/* Numeric time zone, in seconds, for
								 * TimestampTz data type */
		}			datetime;
	}			val;
};
```

We could have protobuf types map to this in-memory structure:

- repeated could be array
- map could be pair

Then, it would be convenient to add more functions that make RPC calls to fetch protobuf responses in this convenient format then convert them to jsonb to output for pg function call.  I already have a small hack poc demonstrating this

```diff
diff --git i/src/postgres/src/backend/utils/misc/pg_yb_utils.c w/src/postgres/src/backend/utils/misc/pg_yb_utils.c
index b2c407d71e3..78ed51a6839 100644
--- i/src/postgres/src/backend/utils/misc/pg_yb_utils.c
+++ w/src/postgres/src/backend/utils/misc/pg_yb_utils.c
@@ -73,6 +73,7 @@
 #include "tcop/utility.h"
 #include "utils/builtins.h"
 #include "utils/datum.h"
+#include "utils/jsonb.h"
 #include "utils/lsyscache.h"
 #include "utils/pg_locale.h"
 #include "utils/rel.h"
@@ -1715,6 +1716,8 @@ yb_servers(PG_FUNCTION_ARGS)
 		{
 			TupleDescInitEntry(tupdesc, (AttrNumber) 9,
 							   "uuid", TEXTOID, -1, 0);
+			TupleDescInitEntry(tupdesc, (AttrNumber) 10,
+							   "jsonb", JSONBOID, -1, 0);
 		}
 		funcctx->tuple_desc = BlessTupleDesc(tupdesc);
 
@@ -1749,6 +1752,70 @@ yb_servers(PG_FUNCTION_ARGS)
 		if (ncols >= expected_ncols)
 		{
 			values[8] = CStringGetTextDatum(server->uuid);
+			JsonbPair pairs[3] = {
+				{
+					.key = {
+						.type = jbvString,
+						.val.string = {
+							.len = 5,
+							.val = "cloud",
+						},
+					},
+					.value = {
+						.type = jbvString,
+						.val.string = {
+							.len = strnlen(server->cloud, 100),
+							.val = pstrdup(server->cloud),
+						},
+					},
+					.order = 0,
+				},
+				{
+					.key = {
+						.type = jbvString,
+						.val.string = {
+							.len = 6,
+							.val = "region",
+						},
+					},
+					.value = {
+						.type = jbvString,
+						.val.string = {
+							.len = strnlen(server->region, 100),
+							.val = pstrdup(server->region),
+						},
+					},
+					.order = 1,
+				},
+				{
+					.key = {
+						.type = jbvString,
+						.val.string = {
+							.len = 4,
+							.val = "zone",
+						},
+					},
+					.value = {
+						.type = jbvString,
+						.val.string = {
+							.len = strnlen(server->zone, 100),
+							.val = pstrdup(server->zone),
+						},
+					},
+					.order = 2,
+				},
+			};
+			JsonbValue jbv = {
+				.type = jbvObject,
+				.val = {
+					.object = {
+						.nPairs = 3,
+						.pairs = pairs,
+					},
+				},
+			};
+			Jsonb *jsonb = JsonbValueToJsonb(&jbv); /* directly use jsonb */
+			values[9] = JsonbPGetDatum(jsonb);
 		}
 		memset(nulls, 0, sizeof(nulls));
 		tuple = heap_form_tuple(funcctx->tuple_desc, values, nulls);
diff --git i/src/postgres/src/include/catalog/pg_proc.dat w/src/postgres/src/include/catalog/pg_proc.dat
index c69737aaa80..df9fca7e309 100644
